INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('for-the-fame-think-again', 'For the Fame...Think Again!', 'During my brief stint working at the Music Copyright Society of Kenya in the licensing department, I got a glimpse on why it is a tad bit difficult to get some of the major music consumers i.e broadcasters to pay…', 'Entertainment', '["broadcasters","creative works","ignorance of the law","MCSK","music","music users","release form","relinquish"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"During my brief stint working at the "},{"type":"text","text":"Music Copyright Society of Kenya","marks":[{"type":"link","attrs":{"href":"http://http://www.mcsk.or.ke/"}}]},{"type":"text","text":" in the licensing department, I got a glimpse on why it is a tad bit difficult to get some of the major music consumers i.e broadcasters to pay royalties."}]},{"type":"figure","attrs":{"key":"wp-content/uploads/2013/01/As-famous-as-Beyonce.jpg","src":null,"alt":"As famous as Beyonce","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"I had the opportunity to speak and interact with a few administration staff in some of these broadcasting stations. Now, one thing that I discovered and found shocking is how artists are quick to sign away their creative rights. I got a whiff that an artist submitting a new single would be presented with a release form which states that the artist gives permission for their song to air for free in exchange for exposure. Why on earth do you want to do this to yourself? Fame is not that important if you are really in it because you have the talent and that you are passionate. Maybe I will not be judged harshly for noting how in such instances the swahili proverb “Kizuri cha jiuza kibaya cha jitembeza” applies. - A good thing needs not to parade itself."}]},{"type":"paragraph","content":[{"type":"text","text":"Now Ms./ Mr. Artist why did you sign that release form? You do know it is a contract, right? A legally binding document. And guess what, you cannot plead ignorance. It may be bliss but it sure is not a defence in any court of law. When you realise that you just gave your cherished creation away on a silver platter, how do you plan to seek legal recourse? How do you dare claim that you have been robbed yet you are the one who robbed yourself? No gun was held to your head while you signed this alleged document, or was there? Yet, come time to collect royalties you want to see a cheque in your name!"}]},{"type":"paragraph","content":[{"type":"text","text":"I am yet to see a copy of this document myself but I believe I was given this information by accident because my efforts to get this document have been futile. So if you are reading this and you are party to such an agreement, please do contact me and come with a copy of this so called contract. However, I will say this, this document is viewed as a safety net by such guilty music users to refrain from paying royalties that they should as directed by MCSK. Through a document of this nature, you relinquished any rights you had to your creative works, and whom do you have to blame?"}]},{"type":"paragraph","content":[{"type":"text","text":"Once again, I am using the D word. Do not be desperate msanii (artist). You are throwing your talent and wasting yourself. Next time be advised before you sign a release form- that is what they call it- with a broadcasting station to gain quick fame and die hungry. Perhaps you do not know this. Broadcasters are in business because of you, because of your music. Why are you throwing it away for useless fame and an empty stomach? Ha! Free marketing and exposure? What bollocks!"}]},{"type":"paragraph","content":[{"type":"text","text":"Excuse my French but I need to be harsh. Like I said, the entertainment industry needs a revolution. For the musicians especially the upcoming ones, seek legal advice before you put a signature on anything. Seek legal consult before jeopardising your sweat. Take a copy of any document that purports to ‘protect’ your creative works or ‘market’ it. It will not hurt to ask that you sit on the document for your review before handing over your music."},{"type":"hardBreak"},{"type":"text","text":"How do you want to be helped if you relinquish your rights because you were desperate for fame? If it’s all for the fame...think again. Will you?"}]}]}', 'During my brief stint working at the Music Copyright Society of Kenya in the licensing department, I got a glimpse on why it is a tad bit difficult to get some of the major music consumers i.e broadcasters to pay royalties.
I had the opportunity to speak and interact with a few administration staff in some of these broadcasting stations. Now, one thing that I discovered and found shocking is how artists are quick to sign away their creative rights. I got a whiff that an artist submitting a new single would be presented with a release form which states that the artist gives permission for their song to air for free in exchange for exposure. Why on earth do you want to do this to yourself? Fame is not that important if you are really in it because you have the talent and that you are passionate. Maybe I will not be judged harshly for noting how in such instances the swahili proverb “Kizuri cha jiuza kibaya cha jitembeza” applies. - A good thing needs not to parade itself.
Now Ms./ Mr. Artist why did you sign that release form? You do know it is a contract, right? A legally binding document. And guess what, you cannot plead ignorance. It may be bliss but it sure is not a defence in any court of law. When you realise that you just gave your cherished creation away on a silver platter, how do you plan to seek legal recourse? How do you dare claim that you have been robbed yet you are the one who robbed yourself? No gun was held to your head while you signed this alleged document, or was there? Yet, come time to collect royalties you want to see a cheque in your name!
I am yet to see a copy of this document myself but I believe I was given this information by accident because my efforts to get this document have been futile. So if you are reading this and you are party to such an agreement, please do contact me and come with a copy of this so called contract. However, I will say this, this document is viewed as a safety net by such guilty music users to refrain from paying royalties that they should as directed by MCSK. Through a document of this nature, you relinquished any rights you had to your creative works, and whom do you have to blame?
Once again, I am using the D word. Do not be desperate msanii (artist). You are throwing your talent and wasting yourself. Next time be advised before you sign a release form- that is what they call it- with a broadcasting station to gain quick fame and die hungry. Perhaps you do not know this. Broadcasters are in business because of you, because of your music. Why are you throwing it away for useless fame and an empty stomach? Ha! Free marketing and exposure? What bollocks!
Excuse my French but I need to be harsh. Like I said, the entertainment industry needs a revolution. For the musicians especially the upcoming ones, seek legal advice before you put a signature on anything. Seek legal consult before jeopardising your sweat. Take a copy of any document that purports to ‘protect’ your creative works or ‘market’ it. It will not hurt to ask that you sit on the document for your review before handing over your music.
How do you want to be helped if you relinquish your rights because you were desperate for fame? If it’s all for the fame...think again. Will you?', 601, 'wp-content/uploads/2013/01/As-famous-as-Beyonce.jpg', '', 'published', '2013-01-23T21:44:09Z', '2013-01-23T21:44:09Z', '2013-01-23T21:50:23Z', 0)
ON CONFLICT (slug) DO NOTHING;
