INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('branding-suicide', 'Branding suicide', 'Are you familiar with the Sprite Ad? “Image is nothing, thirst is everything.” Well I beg to differ. Image is everything, especially for a ‘celebrity’.', 'Entertainment', '["advertising","Africa","branding","celebrities","endorsement deals","Kenya"]', '{"type":"doc","content":[{"type":"figure","attrs":{"key":"wp-content/uploads/2013/01/Beyonce-Pepsi-Endorsment.jpg","src":null,"alt":"Beyonce Pepsi Endorsment","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"Are you familiar with the Sprite Ad? “Image is nothing, thirst is everything.” Well I beg to differ. Image is everything, especially for a ‘celebrity’. As Kenyans we have created the culture that as long as we see you on TV, hear you on radio or read about you in the newspapers and magazines then you are a celeb. So, I shall refer to all such personalities as so...celebrities."}]},{"type":"paragraph","content":[{"type":"text","text":"You know how in "},{"type":"text","text":"a previous blog post","marks":[{"type":"link","attrs":{"href":"https://lizlenjo.com/?p=107"}}]},{"type":"text","text":", I mentioned how desperation is what is killing our industry. Well, it comes up again. If there is one thing our local celebrities are yet to master and understand is the concept of brand management. I think that most are likely not to perceive themselves as brands, which they ideally they should."}]},{"type":"paragraph","content":[{"type":"text","text":"When I look at our local TV ads, I worry. I worry why some of our most celebrated celebrities end up with some brand strangling endorsement deals."}]},{"type":"paragraph","content":[{"type":"text","text":"When a celebrity is involved, it is called an endorsement deal, you dig?"}]},{"type":"paragraph","content":[{"type":"text","text":"Well, this came up in a conversation with Christopher Grey and he brought up some wonderful points for our local celebrities to ponder. There are some brands that ideally a celebrity especially of international stature should not dare consider, like a toilet cleaning agent. Why would you an internationally celebrated brand want to associate your brand with a product such as a toilet cleaning agent? Why? I would like to hear the rationale your manager used to convince you into taking the endorsement deal. Have we as Kenyan celebrities created a culture of money, money and more money is what talks? I am not saying this to be offensive but I am assured beyond doubt that a better deal is likely to come along, so take your time. When a celebrity makes a terrible judgement on an endorsement deal they almost automatically close their brand from getting better, image boosting and more lucrative deals. And this is one mistake an image can hardly recover from with ease. It chases any other endorsement deals that were perhaps lurking in the shadows."}]},{"type":"paragraph","content":[{"type":"text","text":"We should observe and learn a few things from international artists. Case in point, Beyonce Giselle Knowles. She has signed some pretty awesome endorsement deals with luxury products and she makes them covetable. Some of her endorsements include L’Oreal Paris, House of Dereon-which she owns and, Tommy Hilfiger ( True Star fragrance) Giorgio Armani (Diamonds fragrance) and just recently she signed another deal with Pepsi worth $50 million. I stand to be corrected but Beyonce has taken her time in taking endorsement deals and she has been in the entertainment scene for a minute...since she was a teenager and her first endorsement deal was in 2002 with Pepsi. Now this is one artist who has got the concept of brand management to a tee."}]},{"type":"paragraph","content":[{"type":"text","text":"Can you imagine if B was to endorse a product like toilet cleaner or air freshener? Can you imagine what it would do to her brand? As we like to say in swahili colloquialism “Kazi zingine zina wenyewe.” - Some jobs are not for everyone. And if you must do sign such an endorsement, the concept and scripting better be magnificent, or else you and your brand are doomed. At the moment, I am sad to say this, Kenyan ads need a lot of work. The creativity is wanting and if I were a celebrity, I would demand for some originality, colour and sass into the concept or else I wouldn’t willingly commit brand suicide."}]},{"type":"paragraph","content":[{"type":"text","text":"My advice to our local celebrities, “Do not take the first endorsement deal that gets slapped in your face! Take some time out and internalise the stakes involved and what it means for your brand. If you do not have an idea what your brand is yet then take a pass until you are sure. Brand suicide is one hard thing to recover from as a celebrity"}]},{"type":"paragraph","content":[{"type":"text","text":"."}]}]}', 'Are you familiar with the Sprite Ad? “Image is nothing, thirst is everything.” Well I beg to differ. Image is everything, especially for a ‘celebrity’. As Kenyans we have created the culture that as long as we see you on TV, hear you on radio or read about you in the newspapers and magazines then you are a celeb. So, I shall refer to all such personalities as so...celebrities.
You know how in a previous blog post, I mentioned how desperation is what is killing our industry. Well, it comes up again. If there is one thing our local celebrities are yet to master and understand is the concept of brand management. I think that most are likely not to perceive themselves as brands, which they ideally they should.
When I look at our local TV ads, I worry. I worry why some of our most celebrated celebrities end up with some brand strangling endorsement deals.
When a celebrity is involved, it is called an endorsement deal, you dig?
Well, this came up in a conversation with Christopher Grey and he brought up some wonderful points for our local celebrities to ponder. There are some brands that ideally a celebrity especially of international stature should not dare consider, like a toilet cleaning agent. Why would you an internationally celebrated brand want to associate your brand with a product such as a toilet cleaning agent? Why? I would like to hear the rationale your manager used to convince you into taking the endorsement deal. Have we as Kenyan celebrities created a culture of money, money and more money is what talks? I am not saying this to be offensive but I am assured beyond doubt that a better deal is likely to come along, so take your time. When a celebrity makes a terrible judgement on an endorsement deal they almost automatically close their brand from getting better, image boosting and more lucrative deals. And this is one mistake an image can hardly recover from with ease. It chases any other endorsement deals that were perhaps lurking in the shadows.
We should observe and learn a few things from international artists. Case in point, Beyonce Giselle Knowles. She has signed some pretty awesome endorsement deals with luxury products and she makes them covetable. Some of her endorsements include L’Oreal Paris, House of Dereon-which she owns and, Tommy Hilfiger ( True Star fragrance) Giorgio Armani (Diamonds fragrance) and just recently she signed another deal with Pepsi worth $50 million. I stand to be corrected but Beyonce has taken her time in taking endorsement deals and she has been in the entertainment scene for a minute...since she was a teenager and her first endorsement deal was in 2002 with Pepsi. Now this is one artist who has got the concept of brand management to a tee.
Can you imagine if B was to endorse a product like toilet cleaner or air freshener? Can you imagine what it would do to her brand? As we like to say in swahili colloquialism “Kazi zingine zina wenyewe.” - Some jobs are not for everyone. And if you must do sign such an endorsement, the concept and scripting better be magnificent, or else you and your brand are doomed. At the moment, I am sad to say this, Kenyan ads need a lot of work. The creativity is wanting and if I were a celebrity, I would demand for some originality, colour and sass into the concept or else I wouldn’t willingly commit brand suicide.
My advice to our local celebrities, “Do not take the first endorsement deal that gets slapped in your face! Take some time out and internalise the stakes involved and what it means for your brand. If you do not have an idea what your brand is yet then take a pass until you are sure. Brand suicide is one hard thing to recover from as a celebrity
.', 656, 'wp-content/uploads/2013/01/Beyonce-Pepsi-Endorsment.jpg', '', 'published', '2013-01-27T23:46:11Z', '2013-01-27T23:46:11Z', '2013-01-28T19:12:14Z', 0)
