INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('efficient-nanny-services-a-mirage-in-our-times', 'Efficient Nanny Services a mirage in our times...', 'This past week has been a rollercoaster on the domestic front. I had a nanny who almost torched my house down in the name of carelessness.', 'Life & Times', '["common sense","effective","health hazards","Home Science","housekeeping","nanny","safety","safety hazards"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This past week has been a rollercoaster on the domestic front. I had a nanny who almost torched my house down in the name of carelessness. When did things like fire hazards, choking hazards among other health hazards stop from being taken seriously? The blaze expression on her face got me intensely worked up I immediately sent the girl packing back to her home."}]},{"type":"paragraph","content":[{"type":"text","text":"I am now asking myself this question: “What has changed since our mother’s times that getting a dedicated nanny makes it almost impossible?” Perhaps it is because during our mother’s times the darkness of being knowledgeable or ‘dotcom’ as it referred to was still so thick and almost permanently still. Now that is no longer the case and technology has played a huge roll in this."}]},{"type":"paragraph","content":[{"type":"text","text":"I fail to understand why and how someone should leave food on open fire to go hide behind the curtains to receive or make a phone call. Don’t they get it that is a safety hazard to do so? I am now coming to the conclusion that common sense in not so common. I am also wondering whether we should blame our education system. The older 8-4-4 curriculum had one very important subject that has helped me to be an effective home make- Home Science."}]},{"type":"paragraph","content":[{"type":"text","text":"I remember back in the day complaining why I would be made to do such an inconsequential subject. Well, now I see that it is not as inconsequential as I thought. The basic knowledge of how to do a quick running stitch or hem stitch on your favourite skirt’s hanging hem goes a long way or the basic knowledge of separating your laundry for washing."}]},{"type":"paragraph","content":[{"type":"text","text":"In the past year I have seen some terrible house keeping judgement calls but this past one week had me thoroughly afraid. So I ask myself, is reliable and effective nanny care and housekeeping a mirage of our time and generation?"}]},{"type":"paragraph","content":[{"type":"text","text":"I am sure there is someone reading this and asking themselves if I have tried getting one from a bureau or a recruitment agency. The answer is yes. Sad to say this but some of these agencies misrepresent themselves and their services so badly it is hard to trust them as well."}]},{"type":"paragraph","content":[{"type":"text","text":"I refuse to show desperation and tolerate mediocre work in my household. But I hope that perhaps someday soon I shall find the perfect nanny for me. I know how it is a game of luck and I hope luck be a lady soon."}]}]}', 'This past week has been a rollercoaster on the domestic front. I had a nanny who almost torched my house down in the name of carelessness. When did things like fire hazards, choking hazards among other health hazards stop from being taken seriously? The blaze expression on her face got me intensely worked up I immediately sent the girl packing back to her home.
I am now asking myself this question: “What has changed since our mother’s times that getting a dedicated nanny makes it almost impossible?” Perhaps it is because during our mother’s times the darkness of being knowledgeable or ‘dotcom’ as it referred to was still so thick and almost permanently still. Now that is no longer the case and technology has played a huge roll in this.
I fail to understand why and how someone should leave food on open fire to go hide behind the curtains to receive or make a phone call. Don’t they get it that is a safety hazard to do so? I am now coming to the conclusion that common sense in not so common. I am also wondering whether we should blame our education system. The older 8-4-4 curriculum had one very important subject that has helped me to be an effective home make- Home Science.
I remember back in the day complaining why I would be made to do such an inconsequential subject. Well, now I see that it is not as inconsequential as I thought. The basic knowledge of how to do a quick running stitch or hem stitch on your favourite skirt’s hanging hem goes a long way or the basic knowledge of separating your laundry for washing.
In the past year I have seen some terrible house keeping judgement calls but this past one week had me thoroughly afraid. So I ask myself, is reliable and effective nanny care and housekeeping a mirage of our time and generation?
I am sure there is someone reading this and asking themselves if I have tried getting one from a bureau or a recruitment agency. The answer is yes. Sad to say this but some of these agencies misrepresent themselves and their services so badly it is hard to trust them as well.
I refuse to show desperation and tolerate mediocre work in my household. But I hope that perhaps someday soon I shall find the perfect nanny for me. I know how it is a game of luck and I hope luck be a lady soon.', 417, NULL, '', 'published', '2013-02-03T21:20:27Z', '2013-02-03T21:20:27Z', '2013-02-03T21:20:27Z', 0)
ON CONFLICT (slug) DO NOTHING;
