INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'Liz Lenjo', '', 'It is a difficulty we are forced to embrace as new generation mothers. It seems that the days when nannies would retain their jobs for years are long gone. It makes it hard to look for a 9-5 job. The cases of negligent nannies are also discomforting to contemplate a 9-5. These are our times Kinya...sigh!', 'approved', 0, 'imported from WordPress', '2013-08-21T10:57:47Z' FROM posts WHERE slug = 'efficient-nanny-services-a-mirage-in-our-times';
