INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('300-million-released-for-the-local-music-industry', '300 Million Released for the Local Music Industry', 'Finally, some good news for the creatives in the music and film sector. Through the Youth Enterprise Development Fund, the Government has released 300 Million for those in the music industry to borrow and invest in…', 'Entertainment', '["borrow","entertainment","Film","invest","Kenya Broadcasting Corporation","Kenya Film Commission","Kshs. 300M","loan"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finally, some good news for the creatives in the music and film sector. Through the Youth Enterprise Development Fund, the Government has released 300 Million for those in the music industry to borrow and invest in their music. This means musicians, dancers, song writers among other music professionals can borrow money to invest in their productions, pay for studio time, pay for cast and crew for a music shoot, you name it! With all these expenses, now you have a place to borrow money from."}]},{"type":"paragraph","content":[{"type":"text","text":"The Youth Enterprise Fund has also joined hands with the Kenya Film Commission and Kenya Broadcasting Corporation to create the Vijana Film Fund. The aim of the fund is to attract professionals in the film industry to take loans to invest and re-invest in their film businesses. For those who want to venture into production and create films, movies, dramas, you have a way in to make your dream come true and crate a name in the film industry."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a good show by the Government and stake holders in the creative industry to give hope to aspiring artists, musicians, actors, dancers and the likes in the music and film industry. Lack of capital and investors having being one of the key issues that hinder development in these areas, now you have the power to borrow and create."}]},{"type":"paragraph","content":[{"type":"text","text":"My only hope is that we shall utilize these funds for the stated purposes and that transparency shall prevail. As for you my creative fellows, invest wisely and be in it to win it."}]},{"type":"paragraph","content":[{"type":"text","text":"Our industry has a lot of potential, entertain us!"}]},{"type":"paragraph","content":[{"type":"text","text":"http://www.youthfund.go.ke/","marks":[{"type":"link","attrs":{"href":"http://www.youthfund.go.ke/"}}]}]}]}', 'Finally, some good news for the creatives in the music and film sector. Through the Youth Enterprise Development Fund, the Government has released 300 Million for those in the music industry to borrow and invest in their music. This means musicians, dancers, song writers among other music professionals can borrow money to invest in their productions, pay for studio time, pay for cast and crew for a music shoot, you name it! With all these expenses, now you have a place to borrow money from.
The Youth Enterprise Fund has also joined hands with the Kenya Film Commission and Kenya Broadcasting Corporation to create the Vijana Film Fund. The aim of the fund is to attract professionals in the film industry to take loans to invest and re-invest in their film businesses. For those who want to venture into production and create films, movies, dramas, you have a way in to make your dream come true and crate a name in the film industry.
This is a good show by the Government and stake holders in the creative industry to give hope to aspiring artists, musicians, actors, dancers and the likes in the music and film industry. Lack of capital and investors having being one of the key issues that hinder development in these areas, now you have the power to borrow and create.
My only hope is that we shall utilize these funds for the stated purposes and that transparency shall prevail. As for you my creative fellows, invest wisely and be in it to win it.
Our industry has a lot of potential, entertain us!
http://www.youthfund.go.ke/', 268, NULL, '', 'published', '2013-10-07T15:10:45Z', '2013-10-07T15:10:45Z', '2013-10-07T15:12:52Z', 0)
ON CONFLICT (slug) DO NOTHING;
