INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'Tonny Kibet', '', 'Its sad that the culture of capitalism has made this industry a haven for the established to use the content and talent of the up and coming for a fee or free with a lame reason like "we are giving u a platform" take charge of ur intellectual property.... Good read L', 'approved', 0, 'imported from WordPress', '2014-02-05T04:00:11Z' FROM posts WHERE slug = 'robbing-competitions-an-outcry-on-behalf-of-kenyan-poets';
INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'pala', '', 'It is sad that they should ask to be paid and the poets will have to buy the newspaper to look at their published poems that is like Kshs. 1050 shilings to them. Madness i hope no poet stoops that low.', 'approved', 0, 'imported from WordPress', '2014-02-06T05:08:17Z' FROM posts WHERE slug = 'robbing-competitions-an-outcry-on-behalf-of-kenyan-poets';
