INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('liz-lenjos-law-blog-nominated-for-bake-awards-best-topical-blog-vote-for-liz-lenjos-law', 'Liz Lenjo''s Law Blog Nominated for BAKE Awards: Best Topical Blog. Vote For Liz Lenjo''s Law', 'I would like to thank my readers for contributing to the success of this blog. My main goal has been and remains to engage stake holders in all facets of the entertainment, arts and innovations industries and to educate…', 'Life & Times', '["Awards","BAKE","entertainment law","Intellectual Property Law","Nomination","Topical Blog","Vote"]', '{"type":"doc","content":[{"type":"figure","attrs":{"key":"wp-content/uploads/2014/03/BAKE-Logo.jpg","src":null,"alt":"BAKE Logo","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"I would like to thank my readers for contributing to the success of this blog. My main goal has been and remains to engage stake holders in all facets of the entertainment, arts and innovations industries and to educate you on the law, practices as well as keep you current with latest developments as I share my humble opinions to help shape this green yet talented industry."}]},{"type":"paragraph","content":[{"type":"text","text":"As a result, I humbly submit that my blog has been nominated for the Bloggers Association of Kenya (BAKE) Awards 2014. Under the category Best Topical Blog. I would like to request you to help me win in my category by voting for me. Kindly click on the link below and vote:"}]},{"type":"paragraph","content":[{"type":"text","text":"http://www.blogawards.co.ke/vote/","marks":[{"type":"link","attrs":{"href":"http://www.blogawards.co.ke/vote/"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Just one vote from you is all I request for."}]},{"type":"paragraph","content":[{"type":"text","text":"It is humbling to be nominated. I am thankful. Please vote for me and fuel my passion for our creative industry."}]},{"type":"paragraph","content":[{"type":"text","text":"Thank you."}]}]}', 'I would like to thank my readers for contributing to the success of this blog. My main goal has been and remains to engage stake holders in all facets of the entertainment, arts and innovations industries and to educate you on the law, practices as well as keep you current with latest developments as I share my humble opinions to help shape this green yet talented industry.
As a result, I humbly submit that my blog has been nominated for the Bloggers Association of Kenya (BAKE) Awards 2014. Under the category Best Topical Blog. I would like to request you to help me win in my category by voting for me. Kindly click on the link below and vote:
http://www.blogawards.co.ke/vote/
Just one vote from you is all I request for.
It is humbling to be nominated. I am thankful. Please vote for me and fuel my passion for our creative industry.
Thank you.', 153, 'wp-content/uploads/2014/03/BAKE-Logo.jpg', '', 'published', '2014-03-04T20:46:44Z', '2014-03-04T20:46:44Z', '2014-03-04T20:55:43Z', 0)
ON CONFLICT (slug) DO NOTHING;
