INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'karubiu', '', 'A Worthy read... For a Multi-Creative, that''s a good way to lay the facts on the table... Ama people want a Great Depression so that they can understand the power of guarding their property?', 'approved', 0, 'imported from WordPress', '2014-03-18T22:45:39Z' FROM posts WHERE slug = 'top-5-ailments-in-the-creative-industry-part-5-hobby-ism';
