INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('vote-for-lizlenjo-com-best-topical-blog-category-bake-awards', 'Vote for lizlenjo.com - Best Topical Blog Category BAKE Awards', 'Today marks the last day of voting. The Bloggers Association of Kenya (BAKE) will be holding it''s 4th Kenyan Bloggers Awards popularly known as BAKE Awards on the 2nd May 2015 at Nairobi''s Intercontinental Hotel.', 'Copyright', '["BAKE","Blog Awards","Bloggers Association of Kenya","content","lizlenjo.test","lizlenjo.test for Best Topical bLOG","local content","Vote"]', '{"type":"doc","content":[{"type":"figure","attrs":{"key":"wp-content/uploads/2015/04/10928181_1393571560966322_3069403669772254287_o.jpg","src":null,"alt":"10928181_1393571560966322_3069403669772254287_o","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"Today marks the last day of voting."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Bloggers Association of Kenya","marks":[{"type":"link","attrs":{"href":"http://www.bake.co.ke/"}}]},{"type":"text","text":" (BAKE) will be holding it''s 4th Kenyan Bloggers Awards popularly known as BAKE Awards on the 2nd May 2015 at Nairobi''s Intercontinental Hotel. The initiative by the association is to boost and support local bloggers and their content. Blogging is increasingly becoming a conduit to self employment and it desires a level of seriousness. Let us support our own and welcome alternative methods of employment. As a Nation, we are making great strides towards this direction."}]},{"type":"paragraph","content":[{"type":"text","text":"As we congratulate BAKE on their 4th Ceremony, please remember to "},{"type":"text","text":"vote","marks":[{"type":"link","attrs":{"href":"http://www.blogawards.co.ke/vote/"}}]},{"type":"text","text":" for lizlenjo.test for the Best Topical Blog category. This blog aims to educate creatives on their intellectual property rights and equip them with soft skills to make it in the entertainment and creative industries."}]},{"type":"paragraph","content":[{"type":"text","text":"I am humbled by this nomination. Thank you to all my readers for your continued support. Keep reading!!!"}]},{"type":"figure","attrs":{"key":"wp-content/uploads/2015/04/11188429_1001591783199435_8127838160263476972_n.jpg","src":null,"alt":"11188429_1001591783199435_8127838160263476972_n","caption":""}}]}', 'Today marks the last day of voting.
The Bloggers Association of Kenya (BAKE) will be holding it''s 4th Kenyan Bloggers Awards popularly known as BAKE Awards on the 2nd May 2015 at Nairobi''s Intercontinental Hotel. The initiative by the association is to boost and support local bloggers and their content. Blogging is increasingly becoming a conduit to self employment and it desires a level of seriousness. Let us support our own and welcome alternative methods of employment. As a Nation, we are making great strides towards this direction.
As we congratulate BAKE on their 4th Ceremony, please remember to vote for lizlenjo.test for the Best Topical Blog category. This blog aims to educate creatives on their intellectual property rights and equip them with soft skills to make it in the entertainment and creative industries.
I am humbled by this nomination. Thank you to all my readers for your continued support. Keep reading!!!', 152, 'wp-content/uploads/2015/04/10928181_1393571560966322_3069403669772254287_o.jpg', '', 'published', '2015-04-30T11:15:58Z', '2015-04-30T11:15:58Z', '2015-04-30T11:15:58Z', 0)
ON CONFLICT (slug) DO NOTHING;

