INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('craft-afrika-to-convene-the-second-edition-of-afrika-handmade-symposium-and-gallery', 'CRAFT AFRIKA TO CONVENE THE SECOND EDITION OF AFRIKA HANDMADE SYMPOSIUM AND GALLERY', 'Promoting sustainable creative entrepreneurship Craft Afrika is set to host the annual Afrika Handmade Symposium and Gallery. The two week event launches on 30 September with special guest Hon.', 'Copyright', '["buy Kenya build Kenya","copyright","Craft Afrika","craft entrepreneurs","Design Network Africa","design rights","intellectual property rights","licensing"]', '{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Promoting sustainable creative entrepreneurship"}]},{"type":"figure","attrs":{"key":"wp-content/uploads/2015/09/craftafrica.png","src":null,"alt":"craftafrica","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"Craft Afrika is set to host the annual Afrika Handmade Symposium and Gallery. The two week event launches on 30 September with special guest "},{"type":"text","text":"Hon. Adan Mohamed, Cabinet Secretary, Ministry of Industry and Enterprise Development, ","marks":[{"type":"bold"}]},{"type":"text","text":"and runs until 16 October 2015 at Alliance Francaise, Nairobi."}]},{"type":"paragraph","content":[{"type":"text","text":"A market development initiative of Craft Afrika, Afrika Handmade’s objective is to open up new market opportunities for contemporary artisan and design products within the local consumer base."}]},{"type":"paragraph","content":[{"type":"text","text":"The initiative was developed in response to the deeply entrenched notion of what constitutes the sector. Mention the words ‘craft’ or ‘artisan’ and the first thing that comes to mind is the ubiquitous ‘maasai’ market."}]},{"type":"paragraph","content":[{"type":"text","text":"With broad-brush strokes, the sector is depicted as [1] cheap and lacking intrinsic value [2] created for the tourist market [3] lacking product differentiation."}]},{"type":"paragraph","content":[{"type":"text","text":"While this depiction may have some truth in it, there has been, over time, the emergence of a more contemporary genre; one that displays sophistication in style and detail and that answers to the exacting quality demands of a global clientele."}]},{"type":"paragraph","content":[{"type":"text","text":"However, the entrenched and pervasive definition of the sector has denied this genre potential market opportunity, especially within Kenya’s growing middle class."}]},{"type":"paragraph","content":[{"type":"text","text":"“We recognized this as a serious threat to the sustainability of creative enterprises within the sector and that is why we decided to create a platform that could create visibility and access to this genre,” says Christine Gitau, convener of Afrika Handmade."}]},{"type":"paragraph","content":[{"type":"text","text":"The event comes at an opportune time, even as the Ministry of Industry and Enterprise development advocates for increased domestic consumption of locally manufactured goods and services through the "},{"type":"text","text":"Buy Kenya Build Kenya policy","marks":[{"type":"bold"}]},{"type":"text","text":". “We knew it was the right time to begin influencing consumer tastes towards local design. The local market offers viable opportunities for any creative enterprise seeking sustainability, you just need to be proactive and make supply obvious.” she adds."}]},{"type":"paragraph","content":[{"type":"text","text":"In order to deliver on the event’s objective, Afrika Handmade combines a three-in-one experience: a curated gallery, symposium and award ceremony, all geared towards creating visibility for contemporary artisan and design products."}]},{"type":"paragraph","content":[{"type":"text","text":"Collaborating with over 15 designers and artisans sourced from all over Kenya, the two-week Gallery features textile printing from Nanyuki, Lighting solutions for Machakos, basketry from Kisumu, recycled storage products from Kajiado and much more."}]},{"type":"paragraph","content":[{"type":"text","text":"A special feature of the Gallery is "},{"type":"text","text":"Design Network Africa","marks":[{"type":"link","attrs":{"href":"http://www.designnetworkafrica.org/"}}]},{"type":"text","text":" or DNA, a Danish sponsored collective that congregates the finest designers from East and West Africa. The network will be represented by "},{"type":"text","text":"Adele Dejak","marks":[{"type":"link","attrs":{"href":"http://www.adeledejak.com/"}}]},{"type":"text","text":", "},{"type":"text","text":"Bud Panesar","marks":[{"type":"link","attrs":{"href":"http://www.ramara.co.ke/"}}]},{"type":"text","text":", "},{"type":"text","text":"Sky Decor","marks":[{"type":"link","attrs":{"href":"http://sky-decor.com/"}}]},{"type":"text","text":", "},{"type":"text","text":"Uganda Crafts","marks":[{"type":"link","attrs":{"href":"http://www.ugandacrafts2000ltd.org/"}}]},{"type":"text","text":" and "},{"type":"text","text":"Matupo Pottery","marks":[{"type":"link","attrs":{"href":"http://designnetworkafrica.org/people/matupo-pottery/"}}]},{"type":"text","text":" from Zimbabwe."}]},{"type":"paragraph","content":[{"type":"text","text":"Running alongside the Gallery is the "},{"type":"text","text":"2-day symposium","marks":[{"type":"bold"},{"type":"link","attrs":{"href":"http://craftafrika.org/symposium-program/"}}]},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"on"},{"type":"text","text":" 1-2 October","marks":[{"type":"bold"}]},{"type":"text","text":" at the same venue"},{"type":"text","text":". ","marks":[{"type":"bold"}]},{"type":"text","text":"Registration is open to all entrepreneurs working within the sector and will present a great opportunity for networking and"},{"type":"text","text":" ","marks":[{"type":"bold"}]},{"type":"text","text":"information exchange among various stakeholder groups."}]},{"type":"paragraph","content":[{"type":"text","text":"Speakers including Mark Stephenson (MD, "},{"type":"text","text":"Sandstorm","marks":[{"type":"link","attrs":{"href":"http://sandstormkenya.com/"}}]},{"type":"text","text":"), Katungulu Mwendwa ("},{"type":"text","text":"fashion designer","marks":[{"type":"link","attrs":{"href":"http://www.katungulumwendwa.com/"}}]},{"type":"text","text":" and owner MOFTI) and Zohra Baraka (chair, "},{"type":"text","text":"African Women Entrepreneurship Program","marks":[{"type":"link","attrs":{"href":"http://awepkenya.org/"}}]},{"type":"text","text":") will speak on production models, maximizing on technology, AGOA and intellectual property rights session with Liz Lenjo (IP Lawyer- "},{"type":"text","text":"Kikao Law","marks":[{"type":"link","attrs":{"href":"http://www.kikaolaw.com/"}}]},{"type":"text","text":")"}]},{"type":"paragraph","content":[{"type":"text","text":"Curtains come down at Afrika Handmade on 17 October at a Lifetime Achievement Award ceremony honoring "},{"type":"text","text":"Alan Donovan","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Elkana Ongesa","marks":[{"type":"bold"}]},{"type":"text","text":", two of Kenya’s longest serving advocates of the sector."},{"type":"hardBreak"},{"type":"text","text":"About Craft Afrika"},{"type":"hardBreak"},{"type":"text","text":"Founded in 2012, Craft Afrika is a social enterprise that identifies, creates and supports market access opportunities for contemporary artisan and design products, specifically within domestic and regional markets."}]},{"type":"paragraph","content":[{"type":"text","text":"To learn more about us, visit www.craftafrika.org or call +254 717 488 565"}]}]}', 'Promoting sustainable creative entrepreneurship
Craft Afrika is set to host the annual Afrika Handmade Symposium and Gallery. The two week event launches on 30 September with special guest Hon. Adan Mohamed, Cabinet Secretary, Ministry of Industry and Enterprise Development, and runs until 16 October 2015 at Alliance Francaise, Nairobi.
A market development initiative of Craft Afrika, Afrika Handmade’s objective is to open up new market opportunities for contemporary artisan and design products within the local consumer base.
The initiative was developed in response to the deeply entrenched notion of what constitutes the sector. Mention the words ‘craft’ or ‘artisan’ and the first thing that comes to mind is the ubiquitous ‘maasai’ market.
With broad-brush strokes, the sector is depicted as [1] cheap and lacking intrinsic value [2] created for the tourist market [3] lacking product differentiation.
While this depiction may have some truth in it, there has been, over time, the emergence of a more contemporary genre; one that displays sophistication in style and detail and that answers to the exacting quality demands of a global clientele.
However, the entrenched and pervasive definition of the sector has denied this genre potential market opportunity, especially within Kenya’s growing middle class.
“We recognized this as a serious threat to the sustainability of creative enterprises within the sector and that is why we decided to create a platform that could create visibility and access to this genre,” says Christine Gitau, convener of Afrika Handmade.
The event comes at an opportune time, even as the Ministry of Industry and Enterprise development advocates for increased domestic consumption of locally manufactured goods and services through the Buy Kenya Build Kenya policy. “We knew it was the right time to begin influencing consumer tastes towards local design. The local market offers viable opportunities for any creative enterprise seeking sustainability, you just need to be proactive and make supply obvious.” she adds.
In order to deliver on the event’s objective, Afrika Handmade combines a three-in-one experience: a curated gallery, symposium and award ceremony, all geared towards creating visibility for contemporary artisan and design products.
Collaborating with over 15 designers and artisans sourced from all over Kenya, the two-week Gallery features textile printing from Nanyuki, Lighting solutions for Machakos, basketry from Kisumu, recycled storage products from Kajiado and much more.
A special feature of the Gallery is Design Network Africa or DNA, a Danish sponsored collective that congregates the finest designers from East and West Africa. The network will be represented by Adele Dejak, Bud Panesar, Sky Decor, Uganda Crafts and Matupo Pottery from Zimbabwe.
Running alongside the Gallery is the 2-day symposium on 1-2 October at the same venue. Registration is open to all entrepreneurs working within the sector and will present a great opportunity for networking and information exchange among various stakeholder groups.
Speakers including Mark Stephenson (MD, Sandstorm), Katungulu Mwendwa (fashion designer and owner MOFTI) and Zohra Baraka (chair, African Women Entrepreneurship Program) will speak on production models, maximizing on technology, AGOA and intellectual property rights session with Liz Lenjo (IP Lawyer- Kikao Law)
Curtains come down at Afrika Handmade on 17 October at a Lifetime Achievement Award ceremony honoring Alan Donovan and Elkana Ongesa, two of Kenya’s longest serving advocates of the sector.
About Craft Afrika
Founded in 2012, Craft Afrika is a social enterprise that identifies, creates and supports market access opportunities for contemporary artisan and design products, specifically within domestic and regional markets.
To learn more about us, visit www.craftafrika.org or call +254 717 488 565', 583, 'wp-content/uploads/2015/09/craftafrica.png', '', 'published', '2015-09-21T10:54:11Z', '2015-09-21T10:54:11Z', '2015-09-21T11:30:52Z', 0)
