INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'George Mutuli', '', 'First and foremost I would like to appreciate the work you have done on this blog.
To be the business at hand, I agree with you that all stakeholders involved need to consider getting a license. 
According to Dictionary By Farlex, copy right is defined as follows: "A bundle of intangible rights granted by statute to the author or originator of certain literary or artistic productions, whereby, for a limited period, the exclusive privilege is given to that person (or to any party to whom he or she transfers ownership) to make copies of the same for publication and sale." 
In reference to Dela''s cover of Adele''s "Hello", the All Africa   declaration that a cover for Youtube purposes does not amount to copyright infringement is misguided because according to the Youtube Copyright and rights management(https://support.google.com/youtube/answer/2797466)  a video can still be claimed by a copyright owner, even if you have done the following:
1. Given credit to the copyright owner

2. Refrained from monetising the infringing video

3. Noticed similar videos that appear on YouTube

4. Purchased the content on iTunes, a CD or DVD

5. Recorded the content yourself from the TV, cinema or the radio

6. Stated that “no copyright infringement is intended

Exception to the above is where creators allow content of their work to be available for re-use subject to their requirements. For example see the Creative Commons License. (https://support.google.com/youtube/answer/2797468) 

Counsel does the statute of limitation for copyright infringement have any effect on the mentioned examples above?', 'approved', 0, 'imported from WordPress', '2015-12-14T15:38:00Z' FROM posts WHERE slug = 'if-you-do-not-own-it-or-control-it-you-explicitly-need-a-license-a-golden-lesson-kenyan-musicians-need-to-learn';
INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'silomasteve', '', 'The much I love Dela''s cover of hello. Well researched piece. Love it. Can I repost it to http://loitokitok.com/category/know-your-law? At least I have seeked conscent. :-)', 'approved', 0, 'imported from WordPress', '2015-12-14T15:51:49Z' FROM posts WHERE slug = 'if-you-do-not-own-it-or-control-it-you-explicitly-need-a-license-a-golden-lesson-kenyan-musicians-need-to-learn';
INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'Liz Lenjo', '', 'You can share and link it back to my blog and credit on yours. :-)', 'approved', 0, 'imported from WordPress', '2015-12-15T14:46:46Z' FROM posts WHERE slug = 'if-you-do-not-own-it-or-control-it-you-explicitly-need-a-license-a-golden-lesson-kenyan-musicians-need-to-learn';
INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'Liz Lenjo', '', 'Thanks for your comment George. Now, the Terms and Conditions do not supersede the law. However, for You Tube it is a smart move to ensure they protect themselves for the use of their platform which they are responsible for. Look at it this way, where two parties are collaborating on a project and one is an individual or an SME and the other a giant corporate, where the act they are responsible for were to injure you in any way, you would expressly go to the corporate giant for compensation, yes? In this instance, the Terms and Conditions are a cushion for Youtube to protect themselves. However, they in no way purport to invalidate the copyright laws and practices that are global. Please note that by using Youtube one does not transfer ownership.', 'approved', 0, 'imported from WordPress', '2015-12-15T14:53:21Z' FROM posts WHERE slug = 'if-you-do-not-own-it-or-control-it-you-explicitly-need-a-license-a-golden-lesson-kenyan-musicians-need-to-learn';

INSERT INTO posts (slug, title, excerpt, category, tags, body_json, body_text, word_count, cover_key, cover_alt, status, published_at, created_at, updated_at, is_sample)
VALUES ('african-declaration-on-internet-freedoms-why-this-is-relevant-to-kenya', 'AFRICAN DECLARATION ON INTERNET FREEDOMS: WHY THIS IS RELEVANT TO KENYA', 'Have you read the African Declaration on Internet Rights and Freedoms? If you haven’t, you should. As Africans and Kenyans as a whole, we face the risk of our voices being silenced.', 'Life & Times', '["Africa","BAKE","Bloggers Association of Kenya","Citizens","data protection","freedom","internet","Kenya"]', '{"type":"doc","content":[{"type":"figure","attrs":{"key":"wp-content/uploads/2015/12/iFreeKe1-2.jpg","src":null,"alt":"iFreeKe1 (2)","caption":""}},{"type":"paragraph","content":[{"type":"text","text":"Have you read the "},{"type":"text","text":"African Declaration on Internet Rights and Freedoms","marks":[{"type":"link","attrs":{"href":"http://africaninternetrights.org/"}}]},{"type":"text","text":"? If you haven’t, you should. As Africans and Kenyans as a whole, we face the risk of our voices being silenced. This Declaration is a genius idea to document some of the rights we have taken for granted in the digital space."}]},{"type":"paragraph","content":[{"type":"text","text":"The Declaration touches on issues including Openness, Access to the internet, Freedom of Expression, Right to Information, Privacy and Personal Data Protection among many other pertinent issues regarding internet and Constitutional Rights and Freedoms."}]},{"type":"paragraph","content":[{"type":"text","text":"In my opinion, this Declaration if and when endorsed by Kenyans will ensure that we exercise our rights to express ourselves and to share and receive information online. From here we should perhaps think of a more comprehensive document, perhaps a National Internet Freedoms Policy to delve further into these freedoms and ensure consistency with the Constitution of Kenya 2010 to complement the "},{"type":"text","text":"Right to Information Bill 2015","marks":[{"type":"link","attrs":{"href":"http://info.mzalendo.com/media_root/file_archive/Access_to_Information_Bill_2015.pdf"}}]},{"type":"text","text":". Without a doubt, if we let the internet space run like a juggle, as a Nation we may fail miserably. A good balance needs to be attained for prosperity."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Bloggers Association of Kenya (BAKE)","marks":[{"type":"link","attrs":{"href":"http://bake.or.ke/"}}]},{"type":"text","text":" will be hosting an event on the 15th of December at Nailab, 4th Floor at Bishop Magua Centre off Ngong Road. They will be discussing this Declaration and the s"},{"type":"text","text":"tate of internet freedoms in East Africa","marks":[{"type":"link","attrs":{"href":"http://www.cipesa.org/?wpfb_dl=193"}}]},{"type":"text","text":". Members of the public are invited to attend to come and be educated about their rights and freedoms on the internet and also share their thoughts and recommendations. There will also be a viewing of an infomercial style video that will consist of animation, graphics and interviews with Kenyans who use the internet for various purposes that will look to create awareness on the African Declaration on Internet Rights and Freedoms."}]},{"type":"paragraph","content":[{"type":"text","text":"It is every citizen’s responsibilities to know and understand their rights and freedoms. #iFreeKE"}]}]}', 'Have you read the African Declaration on Internet Rights and Freedoms? If you haven’t, you should. As Africans and Kenyans as a whole, we face the risk of our voices being silenced. This Declaration is a genius idea to document some of the rights we have taken for granted in the digital space.
The Declaration touches on issues including Openness, Access to the internet, Freedom of Expression, Right to Information, Privacy and Personal Data Protection among many other pertinent issues regarding internet and Constitutional Rights and Freedoms.
In my opinion, this Declaration if and when endorsed by Kenyans will ensure that we exercise our rights to express ourselves and to share and receive information online. From here we should perhaps think of a more comprehensive document, perhaps a National Internet Freedoms Policy to delve further into these freedoms and ensure consistency with the Constitution of Kenya 2010 to complement the Right to Information Bill 2015. Without a doubt, if we let the internet space run like a juggle, as a Nation we may fail miserably. A good balance needs to be attained for prosperity.
The Bloggers Association of Kenya (BAKE) will be hosting an event on the 15th of December at Nailab, 4th Floor at Bishop Magua Centre off Ngong Road. They will be discussing this Declaration and the state of internet freedoms in East Africa. Members of the public are invited to attend to come and be educated about their rights and freedoms on the internet and also share their thoughts and recommendations. There will also be a viewing of an infomercial style video that will consist of animation, graphics and interviews with Kenyans who use the internet for various purposes that will look to create awareness on the African Declaration on Internet Rights and Freedoms.
It is every citizen’s responsibilities to know and understand their rights and freedoms. #iFreeKE', 311, 'wp-content/uploads/2015/12/iFreeKe1-2.jpg', '', 'published', '2015-12-14T13:56:56Z', '2015-12-14T13:56:56Z', '2015-12-14T13:56:56Z', 0)
ON CONFLICT (slug) DO NOTHING;
