INSERT INTO comments (post_id, name, email, text, status, spam_score, spam_reason, created_at) SELECT id, 'Liz Lenjo', '', 'The aim of this article is not to remove any responsibility from MCSK. However, it for the artists to realize the role they play in ensuring their rights are respected. Also, the need for them to understand the need to participate and respect internal processes to gain credibility as they ascertain their rights.', 'approved', 0, 'imported from WordPress', '2016-02-01T07:46:42Z' FROM posts WHERE slug = 'dissecting-elanis-video-and-music-business-in-kenya-part-1-of-virtual-and-desktop-warfare';
